import backtrader as bt


class MeanReversionStrategy(bt.Strategy):
    def __init__(self):
        self.bollinger = bt.indicators.BollingerBands(
            self.data.close, period=20, devfactor=2
        )
        self.volume_sma_20 = bt.indicators.SMA(self.data.volume, period=20)
        self.rsi = bt.indicators.RSI(self.data.close, period=14)
        self.volume_sma_50 = bt.indicators.SMA(self.data.volume, period=50)
        self.cross_above_mid = bt.indicators.CrossOver(
            self.data.close, self.bollinger.mid
        )

        self.order = None
        self.entry_bar = None
        self.current_day = None
        self.day_start_capital = None
        self.daily_loss_limit_reached = False

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.entry_bar = len(self)
            else:
                self.entry_bar = None
            self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.order = None

    def next(self):
        bar_day = self.data.datetime.date(0)
        if bar_day != self.current_day:
            self.current_day = bar_day
            self.day_start_capital = (
                self.broker.getcash() + self.position.size * self.data.open[0]
            )
            self.daily_loss_limit_reached = False

        current_capital = self.broker.getvalue()
        if current_capital <= self.day_start_capital * (1.0 - 0.005):
            self.daily_loss_limit_reached = True

        if self.order:
            return

        if self.position:
            held_for_three_bars = (
                self.entry_bar is not None and len(self) - self.entry_bar >= 3
            )
            if self.cross_above_mid[0] > 0 or held_for_three_bars:
                self.order = self.close()
            return

        if (
            not self.daily_loss_limit_reached
            and self.data.close[0] < self.bollinger.bot[0]
            and self.data.volume[0] > 1.5 * self.volume_sma_20[0]
            and self.rsi[0] < 30
            and self.volume_sma_50[0] > 1000000
        ):
            self.order = self.buy(size=100)
